package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TaxRec struct { // 01 TAX-REC, 13 bytes
	TrId     string          // PIC X(5) @0 len=5
	TrIncome decimal.Decimal // PIC 9(6)V99 @5 len=8
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                              // PIC X len=1 = "N"
var WsTax decimal.Decimal = decimal.NewFromInt(0)       // PIC 9(7)V99 len=9 = 0
var WsNet decimal.Decimal = decimal.NewFromInt(0)       // PIC 9(7)V99 len=9 = 0
var WsTotalTax decimal.Decimal = decimal.NewFromInt(0) // PIC 9(9)V99 len=11 = 0
var WsCount int64 = 0                                   // PIC 9(3) len=3 = 0
var WsIncEd string                                      // PIC ZZZ,ZZ9.99 len=10
var WsTaxEd string                                      // PIC ZZZ,ZZ9.99 len=10
var WsNetEd string                                      // PIC ZZZ,ZZ9.99 len=10
var WsTotalEd string                                    // PIC ZZ,ZZZ,ZZ9.99 len=13

var TaxRecCurrent TaxRec

var taxFile *os.File
var taxReader *bufio.Reader

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func parsePIC9V99(raw string, scale int) decimal.Decimal {
	digits := ""
	for _, ch := range raw {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		digits = "0"
	}
	d, _ := decimal.NewFromString(digits)
	d = d.Shift(int32(-scale))
	return d
}

func putDecimal(v decimal.Decimal, intDigits int, scale int32, rounded bool) decimal.Decimal {
	var v2 decimal.Decimal
	if rounded {
		v2 = v.Round(scale)
	} else {
		v2 = v.Truncate(scale)
	}
	if v2.IsZero() {
		// ensure positive zero
		if v2.Sign() < 0 {
			v2 = decimal.NewFromInt(0)
		}
		return v2
	}
	sign := v2.Sign()
	abs := v2.Abs()
	intPart := abs.Truncate(0)
	fracPart := abs.Sub(intPart)
	pow10 := decimal.NewFromInt(1).Shift(int32(intDigits))
	// low-order truncation
	truncatedInt := intPart.Mod(pow10)
	resultAbs := truncatedInt.Add(fracPart)
	if sign < 0 {
		resultAbs = resultAbs.Neg()
	}
	return resultAbs
}

func putInt(v int64, width int) int64 {
	pow := int64(1)
	for i := 0; i < width; i++ {
		pow *= 10
	}
	if pow == 0 {
		return v
	}
	if v >= 0 {
		return v % pow
	}
	abs := -v
	rem := abs % pow
	return -rem
}

func formatEdited(v decimal.Decimal, pic string) string {
	dotPos := strings.Index(pic, ".")
	integerPicPart := pic
	decimalPicPart := ""
	if dotPos != -1 {
		integerPicPart = pic[:dotPos]
		decimalPicPart = pic[dotPos+1:]
	}
	intDigits := 0
	for _, ch := range integerPicPart {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	decDigits := 0
	for _, ch := range decimalPicPart {
		if ch == 'Z' || ch == '9' {
			decDigits++
		}
	}

	// absolute truncated value string with decDigits decimals
	absTrunc := v.Abs().Truncate(int32(decDigits))
	fixedStr := absTrunc.StringFixed(int32(decDigits))

	var integerPartStr string
	var decimalPartStr string
	if decDigits > 0 {
		parts := strings.SplitN(fixedStr, ".", 2)
		integerPartStr = parts[0]
		if len(parts) > 1 {
			decimalPartStr = parts[1]
		} else {
			decimalPartStr = strings.Repeat("0", decDigits)
		}
		// pad decimal part to decDigits
		if len(decimalPartStr) < decDigits {
			decimalPartStr += strings.Repeat("0", decDigits-len(decimalPartStr))
		} else if len(decimalPartStr) > decDigits {
			decimalPartStr = decimalPartStr[:decDigits]
		}
	} else {
		integerPartStr = fixedStr
		decimalPartStr = ""
	}

	// overflow: keep low-order digits
	if len(integerPartStr) > intDigits {
		integerPartStr = integerPartStr[len(integerPartStr)-intDigits:]
	} else if len(integerPartStr) < intDigits {
		integerPartStr = strings.Repeat("0", intDigits-len(integerPartStr)) + integerPartStr
	}

	picRunes := []rune(pic)
	outRunes := make([]rune, len(picRunes))

	intIdx := 0
	decIdx := 0
	for i, ch := range picRunes {
		switch ch {
		case 'Z', '9':
			if dotPos != -1 && i > dotPos {
				// decimal part
				if decIdx < len(decimalPartStr) {
					outRunes[i] = rune(decimalPartStr[decIdx])
					decIdx++
				} else {
					outRunes[i] = '0'
				}
			} else {
				if intIdx < len(integerPartStr) {
					outRunes[i] = rune(integerPartStr[intIdx])
					intIdx++
				} else {
					outRunes[i] = '0'
				}
			}
		case ',':
			outRunes[i] = ','
		case '.':
			outRunes[i] = '.'
		default:
			outRunes[i] = ch
		}
	}

	suppressed := true
	for i := 0; i < len(picRunes); i++ {
		chPic := picRunes[i]
		if chPic == 'Z' {
			if suppressed && outRunes[i] == '0' {
				outRunes[i] = ' '
			} else {
				suppressed = false
			}
		} else if chPic == '9' {
			suppressed = false
		} else if chPic == ',' {
			if suppressed {
				outRunes[i] = ' '
			} else {
				outRunes[i] = ','
			}
		} else if chPic == '.' {
			outRunes[i] = '.'
		}
	}

	return string(outRunes)
}

func formatPIC9Int(v int64, width int) string {
	pow := int64(1)
	for i := 0; i < width; i++ {
		pow *= 10
	}
	// v already truncated, but ensure within width for display
	if pow != 0 {
		// keep within width (should already be)
		// we just format with zero pad
	}
	// handle negative sign not needed
	if v < 0 {
		v = -v
	}
	return fmt.Sprintf("%0*d", width, v)
}

func ReadPara() {
	if taxReader == nil {
		WsEofFlag = "Y"
		return
	}
	line, err := taxReader.ReadString('\n')
	isEOF := err == io.EOF
	if err != nil && err != io.EOF {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if len(line) == 0 && isEOF {
		WsEofFlag = "Y"
		return
	}
	// strip trailing newline characters
	line = strings.TrimRight(line, "\r\n")
	if len(line) < 13 {
		line = line + strings.Repeat(" ", 13-len(line))
	} else if len(line) > 13 {
		line = line[:13]
	}
	trId := line[0:5]
	trIncomeRaw := line[5:13]
	trIncome := parsePIC9V99(trIncomeRaw, 2)
	TaxRecCurrent.TrId = trId
	TaxRecCurrent.TrIncome = trIncome
	// if this was EOF with content, next call will hit EOF
	_ = isEOF
}

func ProcessPara() {
	tenThou := decimal.RequireFromString("10000.00")
	fortyThou := decimal.RequireFromString("40000.00")
	thousand := decimal.RequireFromString("1000.00")
	sevenThousand := decimal.RequireFromString("7000.00")
	rate10 := decimal.RequireFromString("0.10")
	rate20 := decimal.RequireFromString("0.20")
	rate30 := decimal.RequireFromString("0.30")

	trIncome := TaxRecCurrent.TrIncome
	var rawTax decimal.Decimal
	if trIncome.Cmp(decimal.NewFromInt(10000)) <= 0 {
		rawTax = trIncome.Mul(rate10)
	} else if trIncome.Cmp(decimal.NewFromInt(40000)) <= 0 {
		diff := trIncome.Sub(tenThou)
		rawTax = thousand.Add(diff.Mul(rate20))
	} else {
		diff := trIncome.Sub(fortyThou)
		rawTax = sevenThousand.Add(diff.Mul(rate30))
	}
	WsTax = putDecimal(rawTax, 7, 2, true)
	netRaw := trIncome.Sub(WsTax)
	WsNet = putDecimal(netRaw, 7, 2, false)
	WsTotalTax = putDecimal(WsTotalTax.Add(WsTax), 9, 2, false)
	WsCount = putInt(WsCount+1, 3)
	WsIncEd = formatEdited(TaxRecCurrent.TrIncome, "ZZZ,ZZ9.99")
	WsTaxEd = formatEdited(WsTax, "ZZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s\n", TaxRecCurrent.TrId, WsIncEd, WsTaxEd, WsNetEd)
	ReadPara()
}

func MainPara() {
	var err error
	taxFile, err = os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			WsEofFlag = "Y"
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		defer taxFile.Close()
		taxReader = bufio.NewReader(taxFile)
		ReadPara()
		for !isInputDone() {
			ProcessPara()
		}
	}
	WsTotalEd = formatEdited(WsTotalTax, "ZZ,ZZZ,ZZ9.99")
	wsCountStr := formatPIC9Int(WsCount, 3)
	fmt.Printf("TAXPAYERS: %s TOTAL TAX: %s\n", wsCountStr, WsTotalEd)
}

func main() {
	MainPara()
}
